ValidationRule.errorConditionFormula:
AND ( pse__Project_Task__r.pse__Project__r.Task_Notes_Required__c	 ,  
   OR (
       OR ( pse__Monday_Hours__c < 0 && ISBLANK(pse__Monday_Notes__c),
            pse__Monday_Hours__c > 0 && ISBLANK(pse__Monday_Notes__c)
           ),
       OR ( pse__Tuesday_Hours__c < 0 && ISBLANK(pse__Tuesday_Notes__c),
            pse__Tuesday_Hours__c > 0 && ISBLANK(pse__Tuesday_Notes__c)
           ),
       OR ( pse__Wednesday_Hours__c < 0 && ISBLANK(pse__Wednesday_Notes__c),
            pse__Wednesday_Hours__c > 0 && ISBLANK(pse__Wednesday_Notes__c)
           ),
       OR ( pse__Thursday_Hours__c < 0 && ISBLANK(pse__Thursday_Notes__c),
            pse__Thursday_Hours__c > 0 && ISBLANK(pse__Thursday_Notes__c)
           ),
       OR ( pse__Friday_Hours__c < 0 && ISBLANK(pse__Friday_Notes__c),
            pse__Friday_Hours__c > 0 && ISBLANK(pse__Friday_Notes__c)
           ),
       OR ( pse__Saturday_Hours__c < 0 && ISBLANK(pse__Saturday_Notes__c),
            pse__Saturday_Hours__c > 0 && ISBLANK(pse__Saturday_Notes__c)
           ),
       OR ( pse__Sunday_Hours__c < 0 && ISBLANK(pse__Sunday_Notes__c),
            pse__Sunday_Hours__c > 0 && ISBLANK(pse__Sunday_Notes__c)
           )
           ))
